from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

class Model(BaseModel):
    param: str
    model_config = {"extra": "allow"}

@app.post("/")
async def model_with_extra(data: Model = Form()):
    return data

def test_pass_extra_list():
    client = TestClient(app)
    resp = client.post(
        "/",
        data={
            "param": "123",
            "param2": ["456", "789"],  # Pass a list of values as extra parameter
        },
    )
    print(f"Status code: {resp.status_code}")
    print(f"JSON response: {resp.json()}")
    assert resp.status_code == 200
    assert resp.json() == {
        "param": "123",
        "param2": ["456", "789"],
    }

def test_pass_extra_single():
    client = TestClient(app)
    resp = client.post(
        "/",
        data={
            "param": "123",
            "param2": "456",  # Pass a single value as extra parameter
        },
    )
    print(f"Status code: {resp.status_code}")
    print(f"JSON response: {resp.json()}")
    assert resp.status_code == 200
    assert resp.json() == {
        "param": "123",
        "param2": "456",
    }

if __name__ == "__main__":
    try:
        test_pass_extra_list()
        print("test_pass_extra_list passed!")
        test_pass_extra_single()
        print("test_pass_extra_single passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
